"use strict";
/**
 * Browser test bundle builder.
 * Produces a single browser_tests.bundle.js that can run in a <script> tag.
 * Uses simple concatenation (no webpack needed) since our modules are
 * self-contained with no Node-specific deps beyond crypto (shimmed).
 */

const fs = require('fs');
const path = require('path');

const dataDir = path.join(__dirname, '..', 'data');

// Read all source files
const treeStore = fs.readFileSync(path.join(dataDir, 'TreeStore.js'), 'utf8');
const directory = fs.readFileSync(path.join(dataDir, 'Directory.js'), 'utf8');
const feed = fs.readFileSync(path.join(dataDir, 'Feed.js'), 'utf8');
const repo = fs.readFileSync(path.join(dataDir, 'Repo.js'), 'utf8');
const database = fs.readFileSync(path.join(dataDir, 'Database.js'), 'utf8');
const nameResolver = fs.readFileSync(path.join(dataDir, 'NameResolver.js'), 'utf8');

// Wrap each module in a closure that provides require/module.exports
function wrapModule(name, source) {
    return `
// ── ${name} ──
__modules['${name}'] = (function() {
    var module = { exports: {} };
    var exports = module.exports;
    var require = function(dep) {
        if (dep === 'crypto') return __cryptoShim;
        var parts = dep.split('/');
        var modName = parts[parts.length - 1];
        if (__modules[modName]) return __modules[modName];
        throw new Error('Module not found: ' + dep);
    };
${source.replace(/^"use strict";?\s*/m, '')}
    return module.exports;
})();
`;
}

const bundle = `
// Safecloud 2.9 Data Structures — Browser Test Bundle
// Auto-generated by browser_bundle.js
(function(window) {
"use strict";

// ── Crypto shim (Web Crypto API) ──
var __cryptoShim = {
    createHash: function(alg) {
        if (alg !== 'sha256') throw new Error('Only sha256 supported');
        var _data = [];
        return {
            update: function(input) {
                if (typeof input === 'string') {
                    _data.push(new TextEncoder().encode(input));
                } else {
                    _data.push(input);
                }
                return this;
            },
            digest: function(enc) {
                // Synchronous fallback: use a simple hash.
                // For the browser bundle we pre-compute with a sync SHA-256.
                // We use SubtleCrypto in a blocking way via a sync wrapper,
                // but since that's not possible, we use a pure-JS SHA-256.
                var totalLen = 0;
                for (var i = 0; i < _data.length; i++) totalLen += _data[i].length;
                var merged = new Uint8Array(totalLen);
                var offset = 0;
                for (var i = 0; i < _data.length; i++) {
                    merged.set(_data[i], offset);
                    offset += _data[i].length;
                }
                var hash = __sha256sync(merged);
                if (enc === 'hex') return hash;
                return hash;
            }
        };
    }
};

// ── Pure JS SHA-256 (synchronous, for browser without async) ──
function __sha256sync(data) {
    // SHA-256 constants
    var K = [
        0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5,
        0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
        0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
        0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
        0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc,
        0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
        0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,
        0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
        0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
        0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
        0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3,
        0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
        0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5,
        0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
        0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
        0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2
    ];

    function rotr(n, x) { return (x >>> n) | (x << (32 - n)); }
    function ch(x, y, z) { return (x & y) ^ (~x & z); }
    function maj(x, y, z) { return (x & y) ^ (x & z) ^ (y & z); }
    function sigma0(x) { return rotr(2, x) ^ rotr(13, x) ^ rotr(22, x); }
    function sigma1(x) { return rotr(6, x) ^ rotr(11, x) ^ rotr(25, x); }
    function gamma0(x) { return rotr(7, x) ^ rotr(18, x) ^ (x >>> 3); }
    function gamma1(x) { return rotr(17, x) ^ rotr(19, x) ^ (x >>> 10); }

    // Pre-processing
    var msg = data;
    var msgLen = msg.length;
    var bitLen = msgLen * 8;

    // Padding
    var padLen = ((56 - (msgLen + 1) % 64) + 64) % 64;
    var padded = new Uint8Array(msgLen + 1 + padLen + 8);
    padded.set(msg);
    padded[msgLen] = 0x80;
    // Length in bits as big-endian 64-bit
    var view = new DataView(padded.buffer);
    view.setUint32(padded.length - 4, bitLen, false);

    // Initial hash values
    var H = [
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
        0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19
    ];

    // Process each 512-bit block
    var W = new Array(64);
    for (var offset = 0; offset < padded.length; offset += 64) {
        for (var t = 0; t < 16; t++) {
            W[t] = view.getUint32(offset + t * 4, false);
        }
        for (var t = 16; t < 64; t++) {
            W[t] = (gamma1(W[t-2]) + W[t-7] + gamma0(W[t-15]) + W[t-16]) | 0;
        }

        var a = H[0], b = H[1], c = H[2], d = H[3];
        var e = H[4], f = H[5], g = H[6], h = H[7];

        for (var t = 0; t < 64; t++) {
            var T1 = (h + sigma1(e) + ch(e, f, g) + K[t] + W[t]) | 0;
            var T2 = (sigma0(a) + maj(a, b, c)) | 0;
            h = g; g = f; f = e;
            e = (d + T1) | 0;
            d = c; c = b; b = a;
            a = (T1 + T2) | 0;
        }

        H[0] = (H[0] + a) | 0;
        H[1] = (H[1] + b) | 0;
        H[2] = (H[2] + c) | 0;
        H[3] = (H[3] + d) | 0;
        H[4] = (H[4] + e) | 0;
        H[5] = (H[5] + f) | 0;
        H[6] = (H[6] + g) | 0;
        H[7] = (H[7] + h) | 0;
    }

    var hex = '';
    for (var i = 0; i < 8; i++) {
        hex += ('00000000' + (H[i] >>> 0).toString(16)).slice(-8);
    }
    return hex;
}

// ── Minimal Buffer shim for browser ──
if (typeof Buffer === 'undefined') {
    window.Buffer = {
        from: function(input, encoding) {
            if (typeof input === 'string') {
                var enc = new TextEncoder();
                var arr = enc.encode(input);
                arr.toString = function(fmt) {
                    if (fmt === 'base64') return btoa(String.fromCharCode.apply(null, this));
                    return new TextDecoder().decode(this);
                };
                return arr;
            }
            if (Array.isArray(input) || input instanceof Uint8Array) {
                var arr = new Uint8Array(input);
                arr.toString = function(fmt) {
                    if (fmt === 'base64') return btoa(String.fromCharCode.apply(null, this));
                    return new TextDecoder().decode(this);
                };
                return arr;
            }
            return input;
        },
        isBuffer: function(obj) { return obj instanceof Uint8Array; }
    };
}

var __modules = {};

${wrapModule('TreeStore', treeStore)}
${wrapModule('Directory', directory)}
${wrapModule('Feed', feed)}
${wrapModule('Repo', repo)}
${wrapModule('Database', database)}
${wrapModule('NameResolver', nameResolver)}

// Export to window
window.SafecloudData = {
    TreeStore: __modules['TreeStore'],
    Directory: __modules['Directory'],
    Feed: __modules['Feed'],
    Repo: __modules['Repo'],
    Database: __modules['Database'],
    NameResolver: __modules['NameResolver']
};

})(window);
`;

const outPath = path.join(__dirname, 'browser_tests.bundle.js');
fs.writeFileSync(outPath, bundle);
console.log('Bundle written to', outPath, '(' + bundle.length + ' bytes)');
